function symptom(msg) { console.error("FAIL: " + msg); process.exit(1); }
function broken(msg) { console.error("ERROR: " + msg); process.exit(2); }
let z;
try { z = require("zod").z; } catch (e) { broken("could not load zod: " + e.message); }
let out;
try {
  out = z.record(z.literal("a").transform(() => "b"), z.string()).parse({ a: "John" });
} catch (e) { broken("parse threw: " + e.message); }
const keys = Object.keys(out).join(",");
if (keys === "a" && out.a === "John") symptom("z.record kept input key a instead of transformed key b");
if (keys !== "b" || out.b !== "John") broken("unexpected output " + JSON.stringify(out));
console.log("OK: z.record applies the key schema transform, output " + JSON.stringify(out));

